<?php $labels=['sopralluoghi'=>'Sopralluoghi','preventivi'=>'Preventivi'];$title=$labels[$module]??ucfirst($module); ?>
<div class="page-head"><div><h1 class="h2"><?= e($title) ?></h1><p class="text-secondary mb-0"><?= $module==='sopralluoghi'?'Valutazioni sul posto o da remoto, con attività e costi stimati.':'Offerte economiche e servizi proposti ai clienti.' ?></p></div><?php if($auth->can($module,'creazione')): ?><a class="btn btn-primary" href="/app/<?= e($module) ?>/nuovo">＋ <?= $module==='preventivi'?'Crea preventivo':'Pianifica sopralluogo' ?></a><?php endif ?></div>
<?php if(!$records): ?><div class="card border-0 shadow-sm"><div class="empty-state"><strong><?= $module==='sopralluoghi'?'Nessun sopralluogo registrato':'Nessun preventivo registrato' ?></strong><p class="mb-3 mt-1"><?= $module==='sopralluoghi'?'Aggiungi il primo sopralluogo per raccogliere rilievi e attività consigliate.':'Crea un preventivo vuoto o avvialo da un sopralluogo completato.' ?></p><?php if($auth->can($module,'creazione')): ?><a class="btn btn-primary" href="/app/<?= e($module) ?>/nuovo"><?= $module==='preventivi'?'Crea il primo preventivo':'Pianifica il primo sopralluogo' ?></a><?php endif ?></div></div>
<?php else: ?><div class="filters"><label class="visually-hidden" for="workflowSearch">Cerca in <?= e($title) ?></label><input class="form-control" type="search" id="workflowSearch" placeholder="Cerca cliente, numero o descrizione" data-live-filter="#workflowRows"></div><div class="table-wrap"><table class="table table-hover align-middle"><thead><tr><?php if($module==='preventivi'): ?><th>Numero</th><th>Cliente</th><th>Preventivo</th><th>Importo indicativo</th><th>Validità</th><th>Stato</th><?php else: ?><th>Data</th><th>Cliente / sede</th><th>Sopralluogo</th><th>Modalità</th><th>Stato</th><?php endif ?><th></th></tr></thead><tbody id="workflowRows">
<?php foreach($records as $row): ?><tr><?php if($module==='preventivi'): $total=max(0,(float)$row['imponibile']-(float)$row['sconto'])*(1+(float)$row['iva']/100); ?><td><strong><?= e($row['numero']) ?></strong></td><td><?= e($row['cliente']) ?></td><td><?= e($row['titolo']) ?></td><td><?= e(number_format($total,2,',','.')) ?> €</td><td><?= e($row['validita_fino']?date('d/m/Y',strtotime($row['validita_fino'])):'—') ?></td><td><span class="badge rounded-pill text-bg-light"><?= e(ucfirst(str_replace('_',' ',$row['stato']))) ?></span></td><?php else: ?><td class="text-nowrap"><?= e($row['pianificato_il']?date('d/m/Y H:i',strtotime($row['pianificato_il'])):'Da pianificare') ?></td><td><strong><?= e($row['cliente']) ?></strong><br><small><?= e($row['sede_nome']?:'Sede da definire') ?></small></td><td><?= e($row['titolo']) ?><?= $row['infestante']?'<br><small>Infestante: '.e($row['infestante']).'</small>':'' ?></td><td><?= e($row['modalita']==='remoto'?'Da remoto':'In presenza') ?></td><td><span class="badge rounded-pill text-bg-light"><?= e(ucfirst(str_replace('_',' ',$row['stato']))) ?></span></td><?php endif ?><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="/app/<?= e($module) ?>/<?= (int)$row['id'] ?>">Apri</a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
